\textbf{3.2.} Let $P$ be a Lebesgue--Stieltjes measure on $\mathbb{R}$ corresponding to a continuous distribution function, i.e., $P$ is a set function on $\mathcal{B}(\mathbb{R})$ and there exists a continuous function $F(x)$ such that $P([a, b]) = F(b) - F(a)$ for all $a < b$, and $P(\mathbb{R}) = 1:
\begin{enumerate}
    \item Show that $P(A) = 0$ for all countable subsets $A$ of $\mathbb{R}$.
    \item If $P(A) = 1$, can we deduce that $A$ is a dense subset of $\mathbb{R}$?
\end{enumerate}

\textbf{3.3.} For $i = 1, 2, 3, \dots$, let $p_i$ be a nonnegative real number such that $\sum_{i=1}^\infty p_i$ is finite. We define a function $\mu$ on $2^{\mathbb{N}}$ by

\[
\mu(A) \triangleq \begin{cases} 
\sum_{i \in A} p_i & \text{if } A \text{ has finite cardinality} \\ 
\infty & \text{if } A \text{ is an infinite set,} 
\end{cases}
\]
for $A \subseteq \mathbb{N}$:
\begin{enumerate}[label=(\alph*)]
    \item Determine whether $\mu$ is finitely additive.
    \item Determine whether $\mu$ is $\sigma$-additive.
\end{enumerate}

\textbf{3.7.} (An alternate definition of $\lambda$-system) Show that the following three conditions are equivalent to the definition of $\lambda$-system in Definition 3.10:
\begin{enumerate}
    \item $\Omega \in \mathcal{L}$.
    \item If $A$ and $B$ are sets in $\mathcal{L}$ and $A \subseteq B$, then $B \setminus A \in \mathcal{L}$.
    \item If $A_1, A_2, A_3, \dots$ is a sequence of \textit{increasing} sets in $\mathcal{L}$, then \cup_{i=1}^{\infty} A_i \in \mathcal{L}$.
\end{enumerate}

\begin{thmbox}{4.1}
Let $(\Omega, \mathcal{F})$ be a measurable space and let $A$ be a subset of $\Omega$. The indicator function
\[
\mathbf{1}_A(\omega) \triangleq \begin{cases} 1 & \text{if } \omega \in A \\ 0 & \text{otherwise.} \end{cases}
\]
is $(\mathcal{F}, \mathcal{B}(\mathbb{R}))$-measurable if and only if $A$ is $\mathcal{F}$-measurable.
\end{thmbox}

\noindent\textit{Proof} We consider four cases. Suppose $B$ is a Borel set that contains 1 but not 0. Then the pre-image $\mathbf{1}_A^{-1}(B)$ is equal to the set $A$. If $B$ is a Borel set that contains 0 but not 1, then $\mathbf{1}_A^{-1}(B) = A^c$. When $B$ contains both 0 and 1, then $\mathbf{1}_A^{-1}(B) = \Omega$. Finally, when $B$ does not contain 0 nor 1, then $\mathbf{1}_A^{-1}(B) = \emptyset$. This exhausts all possibilities of Borel sets $B$ containing 0 or 1.

If $A$ is $\mathcal{F}$-measurable, then the four possible pre-images $A$, $A^c$, $\Omega$, and $\emptyset$ are all in $\mathcal{F}$, and hence, the indicator function $\mathbf{1}_A$ is $\mathcal{F}$-measurable. Otherwise, if $A$ is not in $\mathcal{F}$, then the indicator function is not $\mathcal{F}$-measurable. \hfill $\blacksquare$

\textbf{Example 4.4.3 (Complex Gaussian Random Variable)} \\
The standard complex Gaussian random variable is defined as a complex random variable whose real part and imaginary part are independent real-valued normal random variables with mean 0 and variance $1/2$. We use the notation $Z \sim \mathcal{CN}(0, 1)$ if $Z$ is a complex-valued random variable distributed according to the standard complex Gaussian distribution. The variance of $Z$ is equal to $E[\text{Re}(Z)^2 + \text{Im}(Z)^2] = 1$.

A complex Gaussian random variable $Z$ is \textit{circularly symmetric}, which means that its probability distribution is invariant under rotations in the complex plane, i.e., for any real number $\theta$, the complex random variable $e^{i\theta}Z$ has the same distribution as $Z$. The complex Gaussian distribution is commonly used to model additive noise in wireless communication. Using Python, we can generate $Z \in \mathcal{CN}(0, 1)$ using the following commands:

\begin{verbatim}
from numpy import random
Z = random.normal(0,1/2) + random.normal(0,1/2)*1j
print(Z)  # print the random sample
\end{verbatim}

A sample output is
\begin{verbatim}
(-0.2916888782004312+0.4270105512204956j)
\end{verbatim}
